changeSet.sql:
-- Haut commandement militaire UPDATE pep_function_parser pfp JOIN parser p ON p.id = pfp.parser_id JOIN pep_function f ON f.id = pfp.function_id JOIN pep_category c ON c.id = f.category_id SET pfp.completeness = 'COMPLETE', pfp.covered_scope = 'Chefs d''état-major des armées et des armées de terre, mer et air' WHERE c.country_iso = 'FR' AND f.label LIKE 'Chef d''état-major des armées%' AND p.dataset_name IN ('fr_pep_army', 'fr_pep_jorf');
-- Entreprises publiques d'État (APE) UPDATE pep_function_parser pfp JOIN parser p ON p.id = pfp.parser_id JOIN pep_function f ON f.id = pfp.function_id JOIN pep_category c ON c.id = f.category_id SET pfp.completeness = 'COMPLETE', pfp.covered_scope = 'Dirigeants et représentants de l''État dans les entreprises du portefeuille de l''État (APE)' WHERE c.country_iso = 'FR' AND f.label LIKE 'Dirigeant ou administrateur d''un établissement ou d''une société publique de l''État%' AND p.dataset_name = 'fr_pep_state_enterprises';
-- Rattachement du parser fr_pep_wikidata_positions aux autres fonctions de l'UE INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', TRUE, 'Français exerçant une fonction institutionnelle internationale ou européenne répertoriée', NULL FROM pep_function f JOIN pep_category c ON c.id = f.category_id JOIN parser p ON p.dataset_name = 'fr_pep_wikidata_positions' WHERE c.country_iso = 'FR' AND f.label LIKE 'Français exerçant une autre fonction PEP dans une institution de l''UE%' AND NOT EXISTS (SELECT 1 FROM pep_function_parser pfp WHERE pfp.function_id = f.id AND pfp.parser_id = p.id);

-- Secrétaires d'État fédéraux (71 publiés pour 70 attendus) UPDATE pep_function_parser pfp JOIN parser p ON p.id = pfp.parser_id JOIN pep_function f ON f.id = pfp.function_id JOIN pep_category c ON c.id = f.category_id SET pfp.completeness = 'COMPLETE', pfp.covered_scope = 'Secrétaires d''État parlementaires et secrétaires d''État des ministères fédéraux' WHERE c.country_iso = 'DE' AND f.label LIKE 'Secrétaire d''État parlementaire ou secrétaire d''État%' AND p.dataset_name = 'de_pep_federal_secretaries';
-- BaFin (Direction exécutive, 7 membres publiés pour 7 attendus) UPDATE pep_function_parser pfp JOIN parser p ON p.id = pfp.parser_id JOIN pep_function f ON f.id = pfp.function_id JOIN pep_category c ON c.id = f.category_id SET pfp.completeness = 'COMPLETE', pfp.covered_scope = 'Président et directeurs exécutifs de la BaFin' WHERE c.country_iso = 'DE' AND f.label LIKE 'Président ou directeur exécutif de la BaFin%' AND p.dataset_name = 'de_pep_bafin';
-- Ambassadeurs allemands (216 publiés pour 150 attendus) UPDATE pep_function_parser pfp JOIN parser p ON p.id = pfp.parser_id JOIN pep_function f ON f.id = pfp.function_id JOIN pep_category c ON c.id = f.category_id SET pfp.completeness = 'COMPLETE', pfp.covered_scope = 'Chefs de mission diplomatique et ambassadeurs d''Allemagne' WHERE c.country_iso = 'DE' AND f.label LIKE 'Ambassadeur ou chargé d''affaires de la République fédérale d''Allemagne%' AND p.dataset_name = 'de_pep_diplomats';
